using System;
using System.Reflection;
using NUnit.Framework;
using Spacewars.Simulation;
using Spacewars.Runtime;
namespace Spacewars.Tests.EditMode
{
    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(3,false)][TestCase(9,false)][TestCase(3,true)][TestCase(9,true)]
        public void BodyPagedClearKeepsCapacityColdReuseTailAndFaultedEveryNth(int count,bool names)
        {
            if(names)ExercisePagedClear<NavNameKey>(count,(n,r)=>{var text=NavOwnedText.Copy("cell-"+n,r);return(new NavNameKey(new NavNameReference(text,NavNameRole.Text)),text);});
            else ExercisePagedClear<int>(count,(n,r)=>(n+1,null));
        }
        private static void ExercisePagedClear<T>(int count,Func<int,INavStorageReservation,(T value,NavOwnedStorage temporary)> make)
        {
            void Add(NavPagedList<T> list,int n,INavStorageReservation r){var pair=make(n,r);try{list.Add(pair.value);}finally{pair.temporary?.ReleaseOwner();}}
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var source=NavPagedList<T>.CreateOwned(birth.OwnedReservation(),4);for(int n=0;n<count;n++)Add(source,n,birth.OwnedReservation());source.Seal();birth.Attach(source);birth.Commit(source,_=>{});source.Retain();source.ReleaseOwner();byte[] original=CaptureGraph(hot,source);long originalCharge=Unique(source);int capacity=source.Capacity,directoryCapacity=source.DirectoryCapacity;Assert.Throws<InvalidOperationException>(()=>source.Clear());CollectionAssert.AreEqual(original,CaptureGraph(hot,source));
            Assert.True(hot.TryOpenScope(NavigationPreparationKind.Projection,1,20,out var discover));var counter=new Refusal(discover,int.MaxValue);var trial=source.ForkOwned(counter);discover.Attach(trial);int forkCalls=counter.Calls;trial.Clear();int clearCalls=counter.Calls-forkCalls;Assert.Greater(clearCalls,0);Assert.Zero(trial.Count);Assert.AreEqual(capacity,trial.Capacity);Assert.AreEqual(directoryCapacity,trial.DirectoryCapacity);discover.Discard();Assert.AreEqual(originalCharge,hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            for(int nth=1;nth<=clearCalls;nth++){Assert.True(hot.TryOpenScope(NavigationPreparationKind.Projection,1,30+nth,out var rejection));var refusal=new Refusal(rejection,forkCalls+nth);var failed=source.ForkOwned(refusal);rejection.Attach(failed);Assert.Throws<InvalidOperationException>(()=>failed.Clear());Assert.AreEqual(forkCalls+nth,refusal.Calls);int calls=refusal.Calls;Assert.Throws<InvalidOperationException>(()=>failed.Clear());Assert.Throws<InvalidOperationException>(()=>failed.Seal());Assert.Throws<InvalidOperationException>(()=>failed.ForkOwned(refusal));Assert.Throws<InvalidOperationException>(()=>failed.Add(default));Assert.Throws<InvalidOperationException>(()=>failed.Set(0,default));Assert.AreEqual(calls,refusal.Calls);Assert.Throws<ArgumentException>(()=>CaptureGraph(hot,failed));rejection.Discard();Assert.AreEqual(originalCharge,hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);CollectionAssert.AreEqual(original,CaptureGraph(hot,source));}
            Assert.True(hot.TryOpenScope(NavigationPreparationKind.Projection,1,80,out var operation));var cleared=source.ForkOwned(operation.OwnedReservation());operation.Attach(cleared);cleared.Clear();cleared.Clear();cleared.Seal();cleared.Seal();operation.Commit(cleared,_=>{});Assert.Zero(cleared.Count);Assert.AreEqual(capacity,cleared.Capacity);Assert.AreEqual(directoryCapacity,cleared.DirectoryCapacity);byte[] empty=CaptureGraph(hot,cleared);long emptyCharge=Unique(cleared);
            var directory=(NavStorageDirectory<T>)typeof(NavPagedList<T>).GetField("pages",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(cleared);var page=directory.Get(directory.Count-1);int slot=page.Values.Length-1;T hidden=source[0];NavStoragePayload<T>.Retain(hidden);page.Values[slot]=hidden;byte[] malformed;
            try{malformed=CaptureGraph(hot,cleared);}finally{page.Values[slot]=default;NavStoragePayload<T>.Release(hidden);}CollectionAssert.AreEqual(empty,CaptureGraph(hot,cleared));var corrupt=new NavigationRetentionBudget();Assert.True(corrupt.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var corruptScope));Assert.Throws<ArgumentException>(()=>Decode(malformed,corruptScope.OwnedReservation()));corruptScope.Discard();Assert.Zero(corrupt.PhysicalBytes);Assert.Zero(corrupt.HeldBytes);
            (byte[] partial,byte[] appended,long partialCharge,long appendedCharge) Next(NavigationRetentionBudget budget,NavPagedList<T> start){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Projection,1,100,out var partialScope));var partial=start.ForkOwned(partialScope.OwnedReservation());partialScope.Attach(partial);Add(partial,100,partialScope.OwnedReservation());Add(partial,101,partialScope.OwnedReservation());Assert.AreEqual(capacity,partial.Capacity);Assert.AreEqual(directoryCapacity,partial.DirectoryCapacity);partial.Seal();partialScope.Commit(partial,_=>{});byte[] part=CaptureGraph(budget,partial);long partCharge=Unique(partial);Assert.True(budget.TryOpenScope(NavigationPreparationKind.Projection,1,101,out var appendScope));var appended=partial.ForkOwned(appendScope.OwnedReservation());appendScope.Attach(appended);for(int n=appended.Count;n<=capacity;n++)Add(appended,100+n,appendScope.OwnedReservation());Assert.AreEqual(capacity+1,appended.Count);Assert.AreEqual(capacity+4,appended.Capacity);appended.Seal();appendScope.Commit(appended,_=>{});byte[] full=CaptureGraph(budget,appended);long fullCharge=Unique(appended);appended.ReleaseOwner();partial.ReleaseOwner();return(part,full,partCharge,fullCharge);}
            var expected=Next(hot,cleared);CollectionAssert.AreEqual(empty,CaptureGraph(hot,cleared));CollectionAssert.AreEqual(original,CaptureGraph(hot,source));source.Release();source=null;cleared.ReleaseOwner();cleared=null;directory=null;page=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavPagedList<T>)Decode(empty,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});Assert.Zero(restored.Count);Assert.AreEqual(capacity,restored.Capacity);Assert.AreEqual(directoryCapacity,restored.DirectoryCapacity);Assert.AreEqual(emptyCharge,cold.PhysicalBytes);CollectionAssert.AreEqual(empty,CaptureGraph(cold,restored));var actual=Next(cold,restored);CollectionAssert.AreEqual(expected.partial,actual.partial);CollectionAssert.AreEqual(expected.appended,actual.appended);Assert.AreEqual(expected.partialCharge,actual.partialCharge);Assert.AreEqual(expected.appendedCharge,actual.appendedCharge);CollectionAssert.AreEqual(empty,CaptureGraph(cold,restored));restored.ReleaseOwner();restored=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
        }
    }
}
